def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n >= 99:
        return 'D'

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    last5_opp_def = 0
    last10_opp_def = 0
    last10_my_def = 0

    for i, (m, o) in enumerate(history):
        if o == 'C':
            opp_c += 1
        if i >= n - 5:
            if o == 'D':
                last5_opp_def += 1
        if i >= n - 10:
            if o == 'D':
                last10_opp_def += 1
            if m == 'D':
                last10_my_def += 1

    opp_def = n - opp_c

    if opp_def == n:
        return 'D'

    if opp_def == 0:
        if n >= 20 and rng.random() < 0.35:
            return 'D'
        if my_last == 'D' and opp_last == 'C' and rng.random() < 0.5:
            return 'D'
        return 'C'

    if opp_c >= n - 2 and opp_last == 'C':
        return 'C'

    if opp_c <= 2 and n >= 8:
        return 'D'

    if last5_opp_def >= 4:
        return 'D'

    if last10_opp_def >= 8:
        return 'D'

    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    if opp_last == 'D':
        if same_count >= 4:
            if rng.randint(0, 3) == 0:
                return 'C'
            return 'D'

        if same_count >= 2 and opp_def <= 4:
            if rng.randint(0, 3) == 0:
                return 'C'
            return 'D'

        if opp_def * 2 > n:
            return 'D'

        if n < 95 and rng.randint(0, 6) == 0:
            return 'C'

        return 'D'

    if last10_opp_def >= 5 and rng.random() < 0.55:
        return 'D'

    if my_last == 'D' and opp_def <= 3 and last10_my_def <= 5:
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    if same_count >= 5:
        if n < 90 and rng.randint(0, 9) == 0:
            return 'D'
        return 'C'

    return 'C'
